using System;
using System.Linq;
using System.Drawing;
using System.Windows.Forms;
namespace Touchline {
public static class ClubChoices {
 public static string[] Directions={"资金充裕","板凳充裕","商业帝国","历史豪门","文化型俱乐部"};
 public static double Metric(Game g,Club c,string direction){switch(direction){case "资金充裕":return Math.Max(0,c.Funds);case "板凳充裕":return g.Squad(c.Id).Count();case "商业帝国":return c.Commercial;case "历史豪门":return c.Honor;case "文化型俱乐部":return g.Squad(c.Id).Select(p=>(double)p.Favor).DefaultIfEmpty(0).Average();default:throw new Exception("未知俱乐部方向。");}}
 public static Club[] Candidates(Game g,string direction){var ranked=g.Clubs.OrderByDescending(c=>Metric(g,c,direction)).ToArray();double cutoff=Metric(g,ranked[Math.Min(9,ranked.Length-1)],direction);return ranked.Where(c=>Metric(g,c,direction)>=cutoff).ToArray();}
 public static Club Draw(Game g,string direction,string philosophy){if(!Rules.Philosophies.Contains(philosophy))throw new Exception("未知理念。");var candidates=Candidates(g,direction);var rng=new RandomSource(g);Club c=candidates[rng.Weighted(candidates.Select(x=>Metric(g,x,direction)).ToArray())];g.PlayerClubId=c.Id;c.Philosophy=philosophy;foreach(var other in g.Clubs.Where(x=>x.Id!=c.Id))other.Philosophy=Rules.Philosophies[rng.Next(Rules.Philosophies.Length)];foreach(var club in g.Clubs)Football.Auto(g,club);g.Log("根据“"+direction+"”方向抽中"+c.Name+"，执教理念："+philosophy+"。");return c;}
 public static void Purchase(Game g,string tactic){if(!Rules.Tactics.Contains(tactic)||tactic=="无战术")throw new Exception("请选择一种可购买的战术。");Club c=g.Club(g.PlayerClubId);if(c.Tactics.Contains(tactic))throw new Exception("该战术已经解锁，无需重复购买。");if(c.Funds<1000)throw new Exception("资金不足1000，无法购买。");if(g.Live!=null)throw new Exception("请在比赛结束后购买战术。");c.Funds-=1000;c.Tactics=c.Tactics.Concat(new[]{tactic}).ToArray();g.Log("战术商店：花费1000资金解锁“"+tactic+"”。");}
}
