  var pg=Grid();Columns(pg,"理念","效果");pg.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;pg.Columns[0].FillWeight=20;pg.Columns[1].FillWeight=80;pg.DefaultCellStyle.WrapMode=DataGridViewTriState.True;pg.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells;foreach(string p in Rules.Philosophies)pg.Rows.Add(L10n.T(p),L10n.T(RuleDescriptions.Philosophy[p]));philos.Controls.Add(pg);ReferenceDetail(tactics,tg);ReferenceDetail(philos,pg);
